INSERT INTO public.destinations (slug,name,country,region,image_key,summary,description,best_time,duration,activities,attractions,accommodation,travel_info,faq,sort_order) VALUES ('rwanda','Rwanda','Rwanda','East Africa','rwanda','Land of a thousand hills, mountain gorillas and Africa''s cleanest capital.','Rwanda packs volcanoes, rainforest, savanna and lake shores into a country you can cross in a single day. It is the easiest place in Africa to combine gorilla trekking with big-game viewing, chimpanzee tracking and a genuinely world-class capital city.','June – September and December – February (dry seasons)','4 – 8 days',ARRAY['Gorilla trekking','Golden monkey trekking','Chimpanzee tracking','Big five game drives','Canopy walk','Cultural experiences','Photography']::text[],ARRAY['Volcanoes National Park','Akagera National Park','Nyungwe Forest National Park','Lake Kivu','Kigali Genocide Memorial','King''s Palace Nyanza']::text[],ARRAY['Bisate Lodge (Luxury+)','Five Volcanoes Boutique Hotel (Mid-range)','Ruzizi Tented Lodge (Mid-range)','La Palme Hotel, Musanze (Budget)']::text[],ARRAY['Visa on arrival for most nationalities; East Africa Tourist Visa available.','Gorilla permits cost USD 1,500 per person per trek and must be booked early.','Yellow fever certificate required if arriving from an endemic country.','Currency: Rwandan Franc (RWF). USD widely accepted for tourism services.']::text[],'[{"q":"How fit do I need to be for gorilla trekking?","a":"Moderate fitness is enough. Treks run from one to six hours over muddy, hilly terrain. Porters are available and highly recommended."},{"q":"How far in advance should I book a gorilla permit?","a":"Three to six months ahead for high season. We hold permits on your behalf once a deposit is received."}]'::jsonb,0) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.destinations (slug,name,country,region,image_key,summary,description,best_time,duration,activities,attractions,accommodation,travel_info,faq,sort_order) VALUES ('uganda','Uganda','Uganda','East Africa','uganda','The Pearl of Africa — gorillas, chimps, tree-climbing lions and the Nile.','Uganda offers the widest range of primate experiences on the continent alongside classic savanna parks, the source of the Nile and some of Africa''s most rewarding birding.','June – August and December – February','6 – 12 days',ARRAY['Gorilla trekking','Chimpanzee tracking','Game drives','Boat safari','White water rafting','Hiking']::text[],ARRAY['Bwindi Impenetrable Forest','Queen Elizabeth National Park','Murchison Falls','Kibale Forest','Jinja & the Source of the Nile']::text[],ARRAY['Clouds Mountain Gorilla Lodge (Luxury+)','Mweya Safari Lodge (Mid-range)','Rwakobo Rock (Budget)']::text[],ARRAY['E-visa required in advance for most nationalities.','Gorilla permits cost USD 800 per person.','Long road transfers — consider domestic flights between parks.']::text[],'[{"q":"Rwanda or Uganda for gorillas?","a":"Rwanda is faster and more comfortable to reach; Uganda is more affordable and pairs gorillas with chimps and savanna parks."}]'::jsonb,1) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.destinations (slug,name,country,region,image_key,summary,description,best_time,duration,activities,attractions,accommodation,travel_info,faq,sort_order) VALUES ('kenya','Kenya','Kenya','East Africa','kenya','The original safari country — Maasai Mara, the Great Migration and Indian Ocean beaches.','Kenya combines legendary big-cat viewing in the Maasai Mara with Amboseli''s elephant herds beneath Kilimanjaro and a coastline made for post-safari recovery.','July – October (migration) and January – March','6 – 10 days',ARRAY['Game drives','Hot air balloon safari','Cultural visits','Beach','Photography']::text[],ARRAY['Maasai Mara','Amboseli','Lake Nakuru','Samburu','Diani Beach']::text[],ARRAY['Angama Mara (Luxury+)','Mara Serena (Mid-range)','Sentrim Camps (Budget)']::text[],ARRAY['Electronic Travel Authorisation required before arrival.','Mara migration river crossings peak between August and October.']::text[],'[{"q":"When can I see the river crossings?","a":"Typically late July through October, though the migration is driven by rainfall and dates vary each year."}]'::jsonb,2) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.destinations (slug,name,country,region,image_key,summary,description,best_time,duration,activities,attractions,accommodation,travel_info,faq,sort_order) VALUES ('tanzania','Tanzania','Tanzania','East Africa','tanzania','Serengeti plains, Ngorongoro Crater, Kilimanjaro and Zanzibar in one country.','Tanzania holds the largest concentration of wildlife in Africa. The Serengeti and Ngorongoro Crater deliver year-round game viewing, while Zanzibar closes the trip on white sand.','June – October, and January – February for calving','7 – 14 days',ARRAY['Game drives','Walking safari','Kilimanjaro trek','Snorkelling','Cultural tours']::text[],ARRAY['Serengeti','Ngorongoro Crater','Tarangire','Mount Kilimanjaro','Zanzibar']::text[],ARRAY['Singita Sasakwa (Luxury+)','Serengeti Serena (Mid-range)','Mobile camps (Budget)']::text[],ARRAY['Visa available online or on arrival.','Internal flights strongly recommended between the northern circuit and Zanzibar.']::text[],'[{"q":"Can I combine Serengeti with gorilla trekking?","a":"Yes. A common route is Kigali or Kilimanjaro entry, northern circuit safari, then a flight to Rwanda for gorillas."}]'::jsonb,3) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.destinations (slug,name,country,region,image_key,summary,description,best_time,duration,activities,attractions,accommodation,travel_info,faq,sort_order) VALUES ('congo','Congo','DR Congo','Central Africa','congo','Virunga, Nyiragongo''s lava lake and lowland gorillas for the true adventurer.','Africa''s oldest national park offers eastern lowland gorillas and an overnight climb to the world''s largest lava lake. Travel here is arranged case by case with current security guidance.','June – September and December – February','3 – 6 days',ARRAY['Lowland gorilla trekking','Volcano hiking','Photography','Community visits']::text[],ARRAY['Virunga National Park','Mount Nyiragongo','Lake Kivu shoreline','Goma']::text[],ARRAY['Mikeno Lodge (Mid-range)','Kibumba Tented Camp (Mid-range)']::text[],ARRAY['Permits and entry are arranged through the park authority.','Travel is subject to current security advisories — we confirm feasibility before booking.']::text[],'[{"q":"Is Congo safe to visit?","a":"Access changes with conditions on the ground. We only confirm Congo itineraries when the park is officially open to visitors."}]'::jsonb,4) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.destinations (slug,name,country,region,image_key,summary,description,best_time,duration,activities,attractions,accommodation,travel_info,faq,sort_order) VALUES ('zanzibar','Zanzibar','Tanzania','Indian Ocean','zanzibar','Spice island beaches, dhow sunsets and Stone Town history to finish your safari.','Zanzibar is the classic safari finale: turquoise water, reef diving, a UNESCO-listed old town and some of the best beach lodges in the region.','June – October and December – February','3 – 7 days',ARRAY['Beach','Snorkelling & diving','Dhow cruise','Spice tour','Honeymoon']::text[],ARRAY['Stone Town','Nungwi','Jozani Forest','Mnemba Atoll','Prison Island']::text[],ARRAY['Zuri Zanzibar (Luxury)','Karafuu Beach Resort (Mid-range)','Guest houses (Budget)']::text[],ARRAY['Tanzania visa covers Zanzibar; separate arrival formalities apply.','Modest dress is appreciated outside beach resorts.']::text[],'[{"q":"How many nights should I add?","a":"Three to four nights is the sweet spot after a safari; a week if Zanzibar is your main destination."}]'::jsonb,5) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.packages (slug,title,category,destination_slugs,days,nights,price_from,currency,image_key,short,description,highlights,included,excluded,requirements,cancellation,max_travelers,available_months,accommodation,transport,itinerary,featured,sort_order) VALUES ('4-days-rwanda-gorilla-safari','4 Days Rwanda Gorilla Safari','Gorilla Trekking',ARRAY['rwanda']::text[],4,3,2850,'USD','rwanda','Kigali, Musanze and one unforgettable hour with a mountain gorilla family.','Our signature short safari. You land in Kigali, explore the city, travel north through the terraced hills to Musanze, and spend an hour face to face with a habituated gorilla family in Volcanoes National Park.',ARRAY['One gorilla trekking permit included','Kigali city and memorial tour','Iby''iwacu cultural village experience','Private 4x4 with English-speaking driver-guide']::text[],ARRAY['Gorilla permit (USD 1,500)','3 nights accommodation with breakfast','Private 4x4 transport and fuel','Professional driver-guide','Airport transfers','Bottled water throughout']::text[],ARRAY['International flights','Visa fees','Travel insurance','Tips and personal items']::text[],ARRAY['Minimum age 15 for gorilla trekking','Moderate fitness level','Hiking boots, rain jacket and gloves']::text[],'Free changes up to 60 days before travel. Gorilla permits are non-refundable once purchased; the balance is refundable at 50% within 30 days.',8,'Year round, best June – September','Mid-range lodge in Musanze, boutique hotel in Kigali','Private 4x4 Land Cruiser','[{"day":1,"title":"Arrival in Kigali","details":["Airport pickup and welcome briefing","Kigali city tour","Genocide Memorial visit","Overnight in Kigali"]},{"day":2,"title":"Kigali to Musanze","details":["Scenic transfer through the thousand hills","Cultural village experience","Trek briefing","Overnight in Musanze"]},{"day":3,"title":"Gorilla Trekking","details":["Early briefing at Kinigi headquarters","Trek to a habituated gorilla family","One hour with the gorillas","Afternoon at leisure"]},{"day":4,"title":"Musanze to Kigali","details":["Breakfast and checkout","Craft market stop","Airport drop-off"]}]'::jsonb,true,0) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.packages (slug,title,category,destination_slugs,days,nights,price_from,currency,image_key,short,description,highlights,included,excluded,requirements,cancellation,max_travelers,available_months,accommodation,transport,itinerary,featured,sort_order) VALUES ('7-days-rwanda-uganda-primates','7 Days Rwanda & Uganda Primate Trail','Wildlife Safari',ARRAY['rwanda','uganda']::text[],7,6,4400,'USD','uganda','Gorillas in Volcanoes, chimps in Kibale and big game in Queen Elizabeth.','A cross-border journey combining two gorilla families, chimpanzee tracking and the savanna of Queen Elizabeth National Park with its famous tree-climbing lions.',ARRAY['Gorilla trekking in Rwanda','Chimpanzee tracking in Kibale Forest','Kazinga Channel boat safari','Ishasha tree-climbing lions']::text[],ARRAY['Gorilla and chimpanzee permits','6 nights full board on safari','Private 4x4 and driver-guide','Park entry fees','Boat safari']::text[],ARRAY['International flights','Visas','Insurance','Drinks and tips']::text[],ARRAY['Valid East Africa visa','Good walking fitness','Yellow fever certificate']::text[],'Deposit non-refundable within 45 days of departure. Permits non-refundable.',6,'Year round','Mid-range lodges and tented camps','Private 4x4 Land Cruiser with pop-up roof','[{"day":1,"title":"Kigali arrival","details":["Airport pickup","City orientation","Overnight Kigali"]},{"day":2,"title":"Volcanoes National Park","details":["Transfer to Musanze","Golden monkey trek","Overnight Musanze"]},{"day":3,"title":"Gorilla trekking","details":["Trek briefing","Gorilla encounter","Overnight Musanze"]},{"day":4,"title":"Cross to Uganda","details":["Border crossing at Cyanika","Drive to Queen Elizabeth","Evening game drive"]},{"day":5,"title":"Queen Elizabeth NP","details":["Morning game drive","Kazinga Channel boat cruise","Ishasha sector"]},{"day":6,"title":"Kibale Forest","details":["Transfer to Fort Portal","Crater lakes drive","Overnight Kibale"]},{"day":7,"title":"Chimps & departure","details":["Chimpanzee tracking","Transfer to Entebbe","Departure"]}]'::jsonb,true,1) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.packages (slug,title,category,destination_slugs,days,nights,price_from,currency,image_key,short,description,highlights,included,excluded,requirements,cancellation,max_travelers,available_months,accommodation,transport,itinerary,featured,sort_order) VALUES ('8-days-kenya-tanzania-migration','8 Days Kenya & Tanzania Migration Safari','Wildlife Safari',ARRAY['kenya','tanzania']::text[],8,7,5200,'USD','kenya','Maasai Mara river crossings, Serengeti plains and the Ngorongoro Crater.','Follow the Great Migration across two countries, with time in the Ngorongoro Crater — the highest density of predators anywhere in Africa.',ARRAY['Mara river crossings in season','Ngorongoro Crater floor day','Optional balloon safari','Maasai community visit']::text[],ARRAY['7 nights full board','Park fees','Game drives in 4x4','Inter-country flight','Driver-guide']::text[],ARRAY['Balloon safari','International flights','Visas','Insurance']::text[],ARRAY['Valid passport with 6 months validity','Yellow fever certificate']::text[],'Full refund minus 15% up to 60 days before travel.',6,'July – October best','Luxury tented camps','4x4 safari vehicle and one domestic flight','[{"day":1,"title":"Nairobi arrival","details":["Airport pickup","Overnight Nairobi"]},{"day":2,"title":"Maasai Mara","details":["Flight to the Mara","Afternoon game drive"]},{"day":3,"title":"Mara full day","details":["Full day game drive","Migration crossing points","Maasai village visit"]},{"day":4,"title":"To Serengeti","details":["Border crossing","Northern Serengeti game drive"]},{"day":5,"title":"Serengeti","details":["Sunrise game drive","Optional balloon safari"]},{"day":6,"title":"Ngorongoro","details":["Transfer to the crater rim","Olduvai Gorge stop"]},{"day":7,"title":"Crater floor","details":["Full day crater safari","Picnic lunch at the hippo pool"]},{"day":8,"title":"Departure","details":["Transfer to Kilimanjaro airport"]}]'::jsonb,true,2) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.packages (slug,title,category,destination_slugs,days,nights,price_from,currency,image_key,short,description,highlights,included,excluded,requirements,cancellation,max_travelers,available_months,accommodation,transport,itinerary,featured,sort_order) VALUES ('3-days-kigali-city-culture','3 Days Kigali City & Culture','City Tour',ARRAY['rwanda']::text[],3,2,640,'USD','rwanda','Markets, memorials, coffee, art and the food scene of Africa''s cleanest capital.','A short city break built for business travellers and stopovers, covering Kigali''s history, creative scene and best restaurants.',ARRAY['Genocide Memorial','Kimironko market','Coffee roastery tour','Nyamirambo walking tour']::text[],ARRAY['2 nights hotel with breakfast','City transport','Guide','Entrance fees']::text[],ARRAY['Flights','Lunches and dinners','Tips']::text[],ARRAY['Comfortable walking shoes']::text[],'Free cancellation up to 7 days before arrival.',12,'Year round','Boutique hotel in Kigali','Air-conditioned van','[{"day":1,"title":"Arrival & city orientation","details":["Airport pickup","Sunset at Mount Kigali"]},{"day":2,"title":"History & markets","details":["Genocide Memorial","Kimironko market","Nyamirambo walking tour"]},{"day":3,"title":"Coffee & departure","details":["Coffee roastery","Craft shopping","Airport transfer"]}]'::jsonb,false,3) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.packages (slug,title,category,destination_slugs,days,nights,price_from,currency,image_key,short,description,highlights,included,excluded,requirements,cancellation,max_travelers,available_months,accommodation,transport,itinerary,featured,sort_order) VALUES ('10-days-honeymoon-rwanda-zanzibar','10 Days Rwanda & Zanzibar Honeymoon','Honeymoon',ARRAY['rwanda','zanzibar']::text[],10,9,7900,'USD','zanzibar','Gorillas, Lake Kivu and a barefoot beach finish on the spice island.','Designed for couples: private guiding, romantic dining, a gorilla trek together and five nights on the Indian Ocean.',ARRAY['Private gorilla trek','Lake Kivu boat sunset','Dhow dinner cruise','Beachfront suite']::text[],ARRAY['9 nights luxury accommodation','Gorilla permits','Domestic and regional flights','Private transfers']::text[],ARRAY['International flights','Spa treatments','Insurance']::text[],ARRAY['Minimum age 15 for trekking']::text[],'50% refundable up to 45 days before travel.',2,'Year round','Luxury lodges and beach resort','Private vehicle and flights','[{"day":1,"title":"Kigali arrival","details":["Private transfer","Welcome dinner"]},{"day":2,"title":"To Volcanoes","details":["Scenic drive","Lodge spa afternoon"]},{"day":3,"title":"Gorilla trekking","details":["Trek","Celebration dinner"]},{"day":4,"title":"Lake Kivu","details":["Drive to Rubavu","Sunset boat cruise"]},{"day":5,"title":"Kivu leisure","details":["Coffee island tour","Beach afternoon"]},{"day":6,"title":"Fly to Zanzibar","details":["Kigali to Zanzibar flight","Beach resort check-in"]},{"day":7,"title":"Stone Town","details":["Heritage walking tour","Spice farm"]},{"day":8,"title":"Ocean day","details":["Mnemba snorkelling","Dhow sunset dinner"]},{"day":9,"title":"Leisure","details":["Free day","Couples spa"]},{"day":10,"title":"Departure","details":["Transfer to Zanzibar airport"]}]'::jsonb,true,4) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.packages (slug,title,category,destination_slugs,days,nights,price_from,currency,image_key,short,description,highlights,included,excluded,requirements,cancellation,max_travelers,available_months,accommodation,transport,itinerary,featured,sort_order) VALUES ('6-days-virunga-adventure','6 Days Virunga Volcano Adventure','Adventure',ARRAY['congo','rwanda']::text[],6,5,3300,'USD','congo','Overnight climb to the Nyiragongo lava lake plus lowland gorillas in Virunga.','A hard-earned adventure for confident hikers: an overnight summit of Nyiragongo, a night in a crater-rim shelter, and lowland gorilla trekking in Virunga National Park.',ARRAY['Nyiragongo lava lake summit','Lowland gorilla trek','Lake Kivu crossing','Small group of six']::text[],ARRAY['Park permits','Porter for summit hike','5 nights accommodation','All transfers']::text[],ARRAY['International flights','Visas','Hiking gear rental']::text[],ARRAY['Strong fitness','Warm summit clothing','Minimum age 18']::text[],'Permits non-refundable. Land arrangements 50% refundable within 30 days.',6,'Subject to park opening','Lodges and crater-rim shelters','4x4 and boat transfer','[{"day":1,"title":"Kigali to Gisenyi","details":["Drive west","Lake Kivu evening"]},{"day":2,"title":"Cross to Goma","details":["Border formalities","Virunga briefing"]},{"day":3,"title":"Nyiragongo ascent","details":["Six-hour climb","Night at the crater rim"]},{"day":4,"title":"Descent","details":["Morning descent","Rest at Mikeno Lodge"]},{"day":5,"title":"Lowland gorillas","details":["Gorilla trek","Community project visit"]},{"day":6,"title":"Return","details":["Return to Kigali","Departure"]}]'::jsonb,false,5) ON CONFLICT (slug) DO NOTHING;
