INSERT INTO public.blog_posts (slug,title,category,post_date,read_minutes,image_key,excerpt,body) VALUES ('gorilla-trekking-what-to-expect','Gorilla Trekking in Rwanda: What Actually Happens on the Day','Gorilla Trekking','2026-07-14'::date,7,'rwanda','From the 6am briefing at Kinigi to the one hour that everyone talks about afterwards.',ARRAY['Your day starts early. Briefing at Volcanoes National Park headquarters in Kinigi begins at 7am, and groups of eight are allocated to one of the habituated gorilla families based on fitness and preference.','The trek itself can take anywhere from 45 minutes to six hours each way. Guides stay in radio contact with trackers who located the family at dawn, so the route adapts as the gorillas move.','Once you reach the family, you have exactly one hour. Masks are required, a seven-metre distance is the rule, and flash photography is not allowed. The gorillas set the terms — sometimes a curious juvenile will close the distance themselves.','Hire a porter. It costs a small amount, supports local families who once relied on poaching, and it changes the trek from an endurance test into an experience you can actually enjoy.']::text[]) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.blog_posts (slug,title,category,post_date,read_minutes,image_key,excerpt,body) VALUES ('best-time-to-visit-east-africa','The Best Time to Visit East Africa, Month by Month','Travel Tips','2026-06-02'::date,9,'tanzania','Dry seasons, migration timing, shoulder-season value and when the rains actually help you.',ARRAY['East Africa has two dry seasons and two wet seasons, and the sweet spot depends far more on what you want to see than on the calendar.','June to September is peak season everywhere: dry trails for gorilla trekking, thinning vegetation for game viewing and the migration reaching the Mara.','The long rains in April and May bring the lowest prices of the year. Trails are muddy, but forests are spectacular, birding peaks and you may have a gorilla family entirely to yourself.','January and February are quietly excellent — dry, green and timed with the Serengeti calving season in the southern plains.']::text[]) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.blog_posts (slug,title,category,post_date,read_minutes,image_key,excerpt,body) VALUES ('rwanda-visa-and-entry-requirements','Rwanda Visa & Entry Requirements for Travellers','Visa & Requirements','2026-05-11'::date,5,'rwanda','Visa on arrival, the East Africa Tourist Visa, yellow fever rules and what to carry.',ARRAY['Most nationalities receive a 30-day visa on arrival at Kigali International Airport. There is no need to apply in advance, though the online Irembo portal is available if you prefer.','If your trip covers Rwanda, Uganda and Kenya, the East Africa Tourist Visa is better value and allows multiple entries across all three countries for 90 days.','A yellow fever certificate is required only if you are arriving from a country where the disease is endemic. Carry a printed copy.','Bring your passport with at least six months validity, printed permits, and a card that works internationally — Rwanda is largely cashless in cities.']::text[]) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.blog_posts (slug,title,category,post_date,read_minutes,image_key,excerpt,body) VALUES ('packing-list-for-safari','The Only Safari Packing List You Need','Travel Tips','2026-04-20'::date,6,'kenya','Neutral layers, gaiters, a spare battery and the three things travellers always forget.',ARRAY['Pack neutral colours: khaki, olive, grey and brown. Avoid blue and black, which attract tsetse flies, and bright white, which shows every metre of dust.','For gorilla trekking, add waterproof boots, gardening gloves for grabbing stinging vegetation, gaiters and a rain jacket. Rainforest weather ignores the forecast.','Camera-wise, a 100-400mm lens covers most game viewing. Bring twice as many batteries and memory cards as you think you need — charging in camps is limited.','The three most forgotten items: a soft duffel bag (hard cases don''t fit light aircraft), a headtorch, and a printed copy of your travel insurance.']::text[]) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.testimonials (name,country,trip,rating,quote,sort_order) SELECT 'Sarah & Mark Whitfield','United Kingdom','4 Days Rwanda Gorilla Safari',5,'Berakah rebuilt the itinerary three times until it fit our dates and budget. The gorilla trek was the most moving hour of our lives, and our guide Eric made the whole trip effortless.',0 WHERE NOT EXISTS (SELECT 1 FROM public.testimonials WHERE name = 'Sarah & Mark Whitfield' AND trip = '4 Days Rwanda Gorilla Safari');
INSERT INTO public.testimonials (name,country,trip,rating,quote,sort_order) SELECT 'Daniel Okoth','Kenya','7 Days Rwanda & Uganda Primate Trail',5,'I travel a lot for work and rarely get this level of organisation. Border crossings, permits and lodges were all handled before I even asked.',1 WHERE NOT EXISTS (SELECT 1 FROM public.testimonials WHERE name = 'Daniel Okoth' AND trip = '7 Days Rwanda & Uganda Primate Trail');
INSERT INTO public.testimonials (name,country,trip,rating,quote,sort_order) SELECT 'Anja Müller','Germany','10 Days Rwanda & Zanzibar Honeymoon',5,'They listened. We said quiet, green and no rushing — and that is exactly the honeymoon we got. Zanzibar after the gorillas was the perfect ending.',2 WHERE NOT EXISTS (SELECT 1 FROM public.testimonials WHERE name = 'Anja Müller' AND trip = '10 Days Rwanda & Zanzibar Honeymoon');
INSERT INTO public.testimonials (name,country,trip,rating,quote,sort_order) SELECT 'The Alvarez Family','Spain','Custom 9 day family safari',5,'Travelling with two children aged 9 and 12 is not simple. Berakah designed shorter drives, family rooms and activities the kids actually loved.',3 WHERE NOT EXISTS (SELECT 1 FROM public.testimonials WHERE name = 'The Alvarez Family' AND trip = 'Custom 9 day family safari');